// src/App.js
import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, Link, useLocation, Navigate } from 'react-router-dom';
import Login from './component/Login';
import Signup from './component/Signup';
import HomePage from './component/HomePage';
import AdminLogin from './component/AdminLogin';  // import AdminLogin
import AdminPage from './component/AdminPage';    // import AdminPage
import './App.css';

function App() {
  const [user, setUser] = useState(null);

  const handleLogin = (userData) => {
    setUser(userData);
    localStorage.setItem('userEmail', userData.email);
    localStorage.setItem('userRole', userData.role || 'user'); // store role (default to user)
    localStorage.setItem('username', userData.username || '');
  };

  return (
    <Router>
      <AppContent user={user} onLogin={handleLogin} />
    </Router>
  );
}

// Protected route component to restrict routes to logged-in users
function PrivateRoute({ user, children, redirectTo = '/' }) {
  return user ? children : <Navigate to={redirectTo} replace />;
}

// Admin route component to restrict routes to admins only
function AdminRoute({ user, children, redirectTo = '/' }) {
  if (!user) {
    return <Navigate to={redirectTo} replace />;
  }
  if (user.role !== 'admin') {
    return <Navigate to="/" replace />; // Redirect non-admins to home or login
  }
  return children;
}

function AppContent({ user, onLogin }) {
  const location = useLocation();
  const hideNav = location.pathname === '/home' || location.pathname === '/admin'; // Hide nav on home and admin pages

  return (
    <>
      <Routes>
        <Route path="/" element={<Login onLogin={onLogin} />} />
        <Route path="/signup" element={<Signup />} />
        <Route 
          path="/home" 
          element={
            <PrivateRoute user={user}>
              <HomePage user={user} />
            </PrivateRoute>
          } 
        />
        <Route path="/admin-login" element={<AdminLogin onLogin={onLogin} />} />
        <Route 
          path="/admin" 
          element={
            <AdminRoute user={user}>
              <AdminPage />
            </AdminRoute>
          } 
        />
      </Routes>

      {!hideNav && (
        <nav className="nav-bar">
          <Link to="/">Login</Link>
          <span className="separator">|</span>
          <Link to="/signup">Signup</Link>
        </nav>
      )}
    </>
  );
}

export default App;
